		if i < len(gotLines) {
			got = gotLines[i]
		}
		if i < len(wantLines) {
			expected = wantLines[i]
		}
		if got != expected {
			label := fmt.Sprintf("line %d", i+1)
			if i < len(labels) {
				label = labels[i]
			}
			return fmt.Errorf("%s %s: %s", name, label, firstDifference(got, expected))
		}
	}
	return fmt.Errorf("%s: %s", name, firstDifference(string(result.stdout), want))
}

